x,t,a=s.symbols('x t a',real=True)
def eq(key,name,actual,expected):
 delta=s.simplify(actual-expected);assert delta.equals(0),(key,name,delta)
 r=rows[key];checks.append(dict(id=key,name=name,status='pass',computed=str(actual),expected=str(expected),formula_sha256=hashlib.sha256(r['formula_latex_verified'].encode()).hexdigest()))
def yes(key,name,test):
 assert test,(key,name)
 r=rows[key];checks.append(dict(id=key,name=name,status='pass',formula_sha256=hashlib.sha256(r['formula_latex_verified'].encode()).hexdigest()))
def key(c,y,p,n,sub='whole'):return f'uec_math_{c}:{y}:{p}:{n}:{sub}'
def E(c,y,p,n,name,actual,expected,sub='whole'):eq(key(c,y,p,n,sub),name,actual,expected)
